describe('Google OAuth Login', () => {
  beforeEach(() => {
    cy.visit('/');
    cy.clearCookies();
    cy.clearLocalStorage();
  });

  it('should successfully log in using Google OAuth with valid credentials', () => {
    cy.get('[data-testid="login-page"]').should('be.visible');
    cy.get('[data-testid="google-login-button"]').should('be.visible').click();

    cy.origin('https://accounts.google.com', () => {
      cy.get('input[type="email"]').should('be.visible').type(Cypress.env('GOOGLE_EMAIL'), { delay: 100 });
      cy.get('#identifierNext').click();
      cy.get('input[type="password"]').should('be.visible', { timeout: 10000 }).type(Cypress.env('GOOGLE_PASSWORD'), { delay: 100 });
      cy.get('#passwordNext').click();
    });

    cy.url().should('not.include', 'accounts.google.com');
    cy.get('[data-testid="user-profile-menu"]', { timeout: 15000 }).should('be.visible');
    cy.get('[data-testid="user-email"]').should('contain', Cypress.env('GOOGLE_EMAIL'));
    cy.get('[data-testid="logout-button"]').should('be.visible');
  });

  it('should handle Google OAuth login cancellation gracefully', () => {
    cy.get('[data-testid="google-login-button"]').click();

    cy.origin('https://accounts.google.com', () => {
      cy.get('button[aria-label="Close"]', { timeout: 10000 }).should('be.visible').click();
    });

    cy.url().should('include', '/');
    cy.get('[data-testid="login-page"]').should('be.visible');
    cy.get('[data-testid="user-profile-menu"]').should('not.exist');
  });

  it('should handle invalid Google credentials with error message', () => {
    cy.get('[data-testid="google-login-button"]').click();

    cy.origin('https://accounts.google.com', () => {
      cy.get('input[type="email"]').should('be.visible').type('invalid-email@example.com', { delay: 100 });
      cy.get('#identifierNext').click();
      cy.get('[data-testid="error-message"]', { timeout: 10000 }).should('be.visible').and('contain', 'Couldn\'t find your Google Account');
    });
  });

  it('should persist user session after Google OAuth login', () => {
    cy.get('[data-testid="google-login-button"]').click();

    cy.origin('https://accounts.google.com', () => {
      cy.get('input[type="email"]').type(Cypress.env('GOOGLE_EMAIL'), { delay: 100 });
      cy.get('#identifierNext').click();
      cy.get('input[type="password"]').should('be.visible', { timeout: 10000 }).type(Cypress.env('GOOGLE_PASSWORD'), { delay: 100 });
      cy.get('#passwordNext').click();
    });

    cy.get('[data-testid="user-profile-menu"]', { timeout: 15000 }).should('be.visible');
    cy.get('[data-testid="dashboard"]').should('be.visible');

    cy.reload();

    cy.get('[data-testid="user-profile-menu"]', { timeout: 10000 }).should('be.visible');
    cy.get('[data-testid="user-email"]').should('contain', Cypress.env('GOOGLE_EMAIL'));
  });

  it('should redirect to dashboard after successful Google OAuth login', () => {
    cy.get('[data-testid="google-login-button"]').click();

    cy.origin('https://accounts.google.com', () => {
      cy.get('input[type="email"]').type(Cypress.env('GOOGLE_EMAIL'), { delay: 100 });
      cy.get('#identifierNext').click();
      cy.get('input[type="password"]').should('be.visible', { timeout: 10000 }).type(Cypress.env('GOOGLE_PASSWORD'), { delay: 100 });
      cy.get('#passwordNext').click();
    });

    cy.url({ timeout: 15000 }).should('include', '/dashboard');
    cy.get('[data-testid="dashboard-header"]').should('be.visible');
    cy.get('[data-testid="welcome-message"]').should('contain', 'Welcome');
  });

  it('should handle network errors during Google OAuth flow', () => {
    cy.intercept('POST', '**/oauth/google/callback', { forceNetworkError: true }).as('googleCallback');

    cy.get('[data-testid="google-login-button"]').click();

    cy.origin('https://accounts.google.com', () => {
      cy.get('input[type="email"]').type(Cypress.env('GOOGLE_EMAIL'), { delay: 100 });
      cy.get('#identifierNext').click();
      cy.get('input[type="password"]').should('be.visible', { timeout: 10000 }).type(Cypress.env('GOOGLE_PASSWORD'), { delay: 100 });
      cy.get('#passwordNext').click();
    });

    cy.get('[data-testid="error-message"]', { timeout: 10000 }).should('be.visible').and('contain', 'Connection error');
    cy.get('[data-testid="retry-button"]').should('be.visible');
  });
});
